def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # A vertical 2 beam proceeds until it meets a horizontal 8 bar; the gap in that
    # bar redirects it to the next open vertical lane. Continue all open channels.
    active={j for j,v in enumerate(g[0]) if v==2}
    for i in range(h):
        if 8 in g[i]:
            holes=[j for j,v in enumerate(g[i]) if v==0]
            # Bar gaps are exits. Beam travels horizontally along the bar to each gap.
            # The active ray hitting a given bar makes the gap(s) accessible.
            if active:
                # select gap(s) in same connected open horizontal span as ray entry;
                # if the entry is blocked, the wave turns at nearest gap.
                near=min(holes,key=lambda j:min(abs(j-a) for a in active)) if holes else None
                if near is not None:
                    # horizontal beam traverses zero cells from current column to gap
                    a=min(active,key=lambda x:abs(x-near))
                    for j in range(min(a,near),max(a,near)+1):
                        if g[i][j]==0:g[i][j]=2
                    active={near}
            # Existing tunnels in bars permit beam to continue along each gap
        else:
            for j in active:
                if g[i][j]==0:g[i][j]=2
    return g
